create table public.residence_assessment_campaigns (
 id uuid primary key default gen_random_uuid(),
 title text not null check(char_length(trim(title)) between 1 and 200),
 center text not null check(char_length(trim(center)) between 1 and 200),
 start_date date not null check(extract(isodow from start_date)=1),
 target_count integer not null default 110 check(target_count between 1 and 500),
 revision integer not null default 1 check(revision>0),
 data jsonb not null check(data ?& array['weeks','slots'] and jsonb_typeof(data)='object' and data->>'weeks'='4' and jsonb_typeof(data->'slots')='array' and jsonb_array_length(data->'slots')<=1000)
);
alter table public.residence_assessment_campaigns enable row level security;
revoke all on public.residence_assessment_campaigns from public,anon,authenticated;
grant select,insert,update on public.residence_assessment_campaigns to authenticated;
grant all on public.residence_assessment_campaigns to service_role;
create policy residence_assessment_campaigns_admin on public.residence_assessment_campaigns for all to authenticated
 using ((select auth.uid())='9d2cfdb1-fed6-4f76-b47a-d58507eb14f2'::uuid)
 with check ((select auth.uid())='9d2cfdb1-fed6-4f76-b47a-d58507eb14f2'::uuid);
comment on table public.residence_assessment_campaigns is 'Dated four-week residence assessment agendas. Separate from the recurring weekly timetable. Resident links use internal IDs; no clinical test results stored here.';

-- Load the reviewed ordinary plan only into an entirely empty reference week.
